source('scripts/deployment_lib.R')
base<-tempfile('run_release_audit_',tmpdir='output');dir.create(base);base<-normalizePath(base)
site<-'SYNTHETIC_AUDIT';run<-basename(base);tables<-file.path(base,'tables');dir.create(tables)
t<-as.POSIXct('2020-01-01 12:00:00',tz='UTC')
arrow::write_parquet(data.frame(recorded_dttm=t),file.path(tables,'clif_vitals.parquet'))
naive<-arrow::Table$create(recorded_dttm=arrow::Array$create(t,type=arrow::timestamp('us')))
arrow::write_parquet(naive,file.path(tables,'clif_respiratory_support.parquet'))
cfg<-list(site_name=site,repo=clif_root,tables_path=tables,analysis=list(run_id=run));config<-file.path(base,'config.json');deploy_json(cfg,config)
ret<-file.path(clif_root,'output',paste0('run_',site,'_',run,'_federated'),'stage1_return');dir.create(ret,recursive=TRUE)
readr::write_csv(tibble::tibble(category='synthetic',n=10),file.path(ret,'counts.csv'));deploy_finish(ret,'stage1',site)
reference<-list(source_files_md5=deploy_source_inventory(),r_version=as.character(getRversion()),r_packages=list(jsonlite=as.character(packageVersion('jsonlite'))))
ref<-file.path(base,'reference.json');deploy_json(reference,ref);out<-file.path(base,'audit')
status<-system2(file.path(R.home('bin'),'Rscript'),c('--vanilla','scripts/site_release_audit.R',shQuote(config),shQuote(ref),shQuote(out)),stdout=file.path(base,'audit.log'),stderr=file.path(base,'audit.log'))
if(status!=0){cat(readLines(file.path(base,'audit.log')),sep='\n');stop('Release audit failed.')}
a<-deploy_read(file.path(out,'audit_summary.json'));z<-read.csv(file.path(out,'timestamp_schema.csv'))
stopifnot(!a$release_approved,!a$source_table_rows_or_patient_rows_read,a$source_schema_metadata_read,!a$original_return_or_caches_modified)
stopifnot(z$review[z$table=='vitals']=='timezone_encoded_in_schema',z$review[z$table=='respiratory_support']=='naive_timezone_requires_site_confirmation')
stopifnot(length(a$source_files_differing_from_reference)==0L)
# Missing files are reported; the script does not rebuild hashes to bless them.
unlink(file.path(ret,'counts.csv'));out2<-file.path(base,'audit_missing')
status<-system2(file.path(R.home('bin'),'Rscript'),c('--vanilla','scripts/site_release_audit.R',shQuote(config),shQuote(ref),shQuote(out2)),stdout=file.path(base,'missing.log'),stderr=file.path(base,'missing.log'))
stopifnot(status==0,deploy_read(file.path(out2,'audit_summary.json'))$packet_integrity[[1]]$status=='missing')
unlink(dirname(ret),recursive=TRUE)
cat('PASS: release audit reads schema metadata, distinguishes aware/naive timestamps, preserves originals, reports missing packets and never approves release\n')
